// Identifiers. Room codes are 4 letters without look-alikes; claim codes are 6 characters; everything
// else is a short random id. All of these are generated by the client that creates the thing, so they
// use real randomness; the room's seeded streams are only for game outcomes.
const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ';          // no I, L, O
const CLAIM_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';  // no 0/1 either
function rand() {
  if (globalThis.crypto?.getRandomValues) { const a = new Uint32Array(1); globalThis.crypto.getRandomValues(a); return a[0] / 4294967296; }
  return Math.random();
}
const fromAlphabet = (alphabet, n) => Array.from({ length: n }, () => alphabet[Math.floor(rand() * alphabet.length)]).join('');
export const roomCode = () => fromAlphabet(CODE_ALPHABET, 4);
export const claimCode = () => fromAlphabet(CLAIM_ALPHABET, 6);
export const shortId = (prefix = '') => prefix + Math.floor(rand() * 2 ** 48).toString(36).padStart(10, '0').slice(-10);
export const uuid = () => (globalThis.crypto?.randomUUID ? globalThis.crypto.randomUUID() : shortId('u-') + shortId());
export const seed32 = () => Math.floor(rand() * 4294967296) >>> 0;
export const normalizeCode = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6);
// The GM PIN is only ever stored hashed. This is a gate between friends, not a vault.
export async function hashPin(pin, salt = 'gwf-rpg') {
  const data = new TextEncoder().encode(`${salt}:${String(pin)}`);
  if (globalThis.crypto?.subtle) { const buf = await globalThis.crypto.subtle.digest('SHA-256', data); return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join(''); }
  let h = 5381; for (const c of data) h = ((h << 5) + h + c) >>> 0; return 'weak-' + h.toString(16);
}
